#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

TAXONOMY_SHA256 = "36a9e0e12c62b8e5543f425ff9940d224848a69e1903f5fb418c531beef6c2a6"
TAXONOMY_GZIP_B64 = """"""

CASES_GZIP_B64 = """"""


def decode(payload: str) -> bytes:
    return gzip.decompress(base64.b64decode(payload))


def write_generated(path: Path, payload: str, expected_sha256: str | None = None) -> None:
    data = decode(payload)
    if expected_sha256 is not None:
        actual = hashlib.sha256(data).hexdigest()
        if actual != expected_sha256:
            raise SystemExit(f"generated payload checksum mismatch for {path}: {actual}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one match, got {count}")
    return text.replace(old, new, 1)


write_generated(ROOT / "examples/resource-taxonomy.ru.yaml", TAXONOMY_GZIP_B64, TAXONOMY_SHA256)
write_generated(ROOT / "examples/routing-cases.ru.json", CASES_GZIP_B64)

